node --input-type=module <<'NODE'
import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import crypto from 'node:crypto';
import * as esbuild from 'esbuild';
const root=process.cwd();
const version=fs.readFileSync('src/sdk/version.ts','utf8').match(/'([^']+)'/)[1];
const banner=`/* edge-personalization SDK v${version} — one package: core (identity, transport), emit (four capture paths), listen (decisions). */`;
const common={bundle:true,platform:'browser',target:'es2022',minify:false,sourcemap:false,legalComments:'none',logLevel:'info',metafile:true,banner:{js:banner},write:false};
const results=[];
for(const [entry,output,format] of [['src/sdk/index.ts','public/sdk/edge-personalization.esm.js','esm'],['src/sdk/browser.ts','public/sdk/edge-personalization.js','iife']]){
 const result=await esbuild.build({...common,entryPoints:[path.join(root,entry)],outfile:path.join(root,output),format});
 const bytes=result.outputFiles[0].contents;assert.deepEqual(Buffer.from(bytes),fs.readFileSync(output));
 results.push({path:output,bytes:bytes.length,sha256:crypto.createHash('sha256').update(bytes).digest('hex'),inputs:Object.keys(result.metafile.inputs).sort()});
}
console.log(JSON.stringify({at:new Date().toISOString(),parity:'PASS',results}));
NODE

node --input-type=module <<'NODE'
import fs from 'node:fs';import crypto from 'node:crypto';import assert from 'node:assert/strict';
const sha=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const b=JSON.parse(fs.readFileSync('docs/remediation/design/W09.05/baseline.json','utf8'));
const owned=new Set(b.owned.map(x=>x.path));const protectedPins=b.pins.filter(x=>!owned.has(x.path));
const mismatches=protectedPins.filter(x=>sha(x.path)!==x.sha256).map(x=>x.path);assert.deepEqual(mismatches,[]);
console.log(JSON.stringify({final_source_stop:{at:new Date().toISOString(),files:b.owned.map(x=>({path:x.path,sha256:sha(x.path)}))},protected_source_comparison:{checked:protectedPins.length,mismatches},records:{baseline:{path:'docs/remediation/design/W09.05/baseline.json',sha256:sha('docs/remediation/design/W09.05/baseline.json')},plan:{path:'docs/remediation/design/W09.05/plan.md',sha256:sha('docs/remediation/design/W09.05/plan.md')},admission:{path:'docs/remediation/evidence/W09.05/admission.json',sha256:sha('docs/remediation/evidence/W09.05/admission.json')}}}));
